import sys
from collections import deque

sys.setrecursionlimit(10000)
tokens = sys.stdin.read().split()

class Node:
    def __init__(self, v):
        self.v = v
        self.l = None
        self.r = None

root = Node(int(tokens[0]))
q = deque([root])
i = 1
while q and i < len(tokens):
    node = q.popleft()
    if i < len(tokens) and tokens[i] != 'null':
        node.l = Node(int(tokens[i]))
        q.append(node.l)
    i += 1
    if i < len(tokens) and tokens[i] != 'null':
        node.r = Node(int(tokens[i]))
        q.append(node.r)
    i += 1

first_left = {}
def dfs_left(node, d):
    if node is None:
        return
    if d not in first_left:
        first_left[d] = node.v
    dfs_left(node.l, d + 1)
    dfs_left(node.r, d + 1)

first_right = {}
def dfs_right(node, d):
    if node is None:
        return
    if d not in first_right:
        first_right[d] = node.v
    dfs_right(node.r, d + 1)
    dfs_right(node.l, d + 1)

dfs_left(root, 0)
dfs_right(root, 0)
res = [first_left[d] for d in sorted(first_left)] + [first_right[d] for d in sorted(first_right) if d >= 1]
print(' '.join(map(str, res)))

