      node.left = { val: Number(tokens[i]), left: null, right: null }
      q.push(node.left)
    }
    i++
    if (i < tokens.length && tokens[i] !== 'null') {
      node.right = { val: Number(tokens[i]), left: null, right: null }
      q.push(node.right)
    }
    i++
  }
  return root
}

